Lemma das_loop : forall L (cur kti kid kname K : Z)
    ra sp gp tp t0 t1 t2 s0 s1 a1 a2 a6 a7 s2 s3 s5 s6 s7 s8 s10 s11 t3 t4 t5 t6 (F : bvmap 5 word) fc (m : mem),
  ASvcChain m cur L -> L <> [] ->
  Forall (fun e => keys_match kti kid kname e = false) L ->
  ro_cells bsegs m K [C8 (wz kti); C8 (wz kid)] -> accessible m K 16 -> K mod 8 = 0 ->
  (kti <> 0 -> ati_ok m kti kname) ->
  0 <= kti < 2^64 -> 0 <= kid < 2^64 -> 0 <= kname < 2^64 ->
  ACONST m -> mem_inv bsegs m ->
  evt bsegs (fun ms' => exists a1' a2' a6',
               ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 (K + 8)) a1' a2' (Z_to_bv 64 0)
                             (Z_to_bv 64 (Z.shiftr K 3 + 2147450880)) (Z_to_bv 64 (Z.shiftr (K + 8) 3 + 2147450880)) a6' a7
                             s2 s3 (Z_to_bv 64 K) s5 s6 s7 s8 (Z_to_bv 64 2147450880) s10 s11 t3 t4 t5 t6)
                        F (Z_to_bv 64 P_A_DAS_SCAN_DONE) fc None m (seg_rom bsegs))
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 (K + 8)) a1 a2 (Z_to_bv 64 cur)
             (Z_to_bv 64 (Z.shiftr K 3 + 2147450880)) (Z_to_bv 64 (Z.shiftr (K + 8) 3 + 2147450880)) a6 a7
             s2 s3 (Z_to_bv 64 K) s5 s6 s7 s8 (Z_to_bv 64 2147450880) s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_DAS_LOOP) fc None m (seg_rom bsegs)).
